import { expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");

  // Act
  const response = await member.post("/api/auth/logout");

  // Assert
  await expectStatus(response, 204);
  const cookies = response
    .headersArray()
    .filter((h) => h.name.toLowerCase() === "set-cookie")
    .map((h) => h.value)
    .filter((value) => value.startsWith("session="));
  expect(cookies, "the response clears the session cookie").toHaveLength(1);
  const cookie = cookies[0];
  const cleared =
    cookie.startsWith("session=;") ||
    /max-age=0/i.test(cookie) ||
    /expires=Thu, 01 Jan 1970/i.test(cookie);
  expect(cleared, `session cookie is cleared: ${cookie}`).toBe(true);
});
